    if k > len(s2):
        return False
    need, window = [0] * 26, [0] * 26
    for ch in s1:
        need[ord(ch) - ord("a")] += 1
    for right, ch in enumerate(s2):
        window[ord(ch) - ord("a")] += 1
        if right >= k:
            window[ord(s2[right - k]) - ord("a")] -= 1   # drop the letter that left
        if window == need:
