    result = []
    for right, ch in enumerate(s):
        window[ord(ch) - ord("a")] += 1
        if right >= k:
            window[ord(s[right - k]) - ord("a")] -= 1
        if right >= k - 1 and window == need:
            result.append(right - k + 1)
    return result

def min_subarray_len(target, nums):
