            if i > start and candidates[i] == candidates[i - 1]:
                continue                 # same value at this level: skip
            if candidates[i] > remaining:
                break
            path.append(candidates[i])
            backtrack(i + 1, remaining - candidates[i])   # each number once
            path.pop()

    backtrack(0, target)
    return result

def letter_combinations(digits):
    if not digits:
        return []
    letters = {"2": "abc", "3": "def", "4": "ghi", "5": "jkl",
               "6": "mno", "7": "pqrs", "8": "tuv", "9": "wxyz"}
    result = []

    def backtrack(i, path):
        if i == len(digits):
            result.append(path)
            return
        for ch in letters[digits[i]]:
            backtrack(i + 1, path + ch)

    backtrack(0, "")
    return result

def generate_parenthesis(n):
    result = []

    def backtrack(path, opened, closed):
        if len(path) == 2 * n:
            result.append(path)
            return
        if opened < n:
            backtrack(path + "(", opened + 1, closed)
        if closed < opened:                   # only close what is open
            backtrack(path + ")", opened, closed + 1)

    backtrack("", 0, 0)
    return result

def exist(board, word):
    rows, cols = len(board), len(board[0])

    def dfs(r, c, i):
        if i == len(word):
            return True
        if not (0 <= r < rows and 0 <= c < cols) or board[r][c] != word[i]:
            return False
        board[r][c] = "#"                     # used on this path
        found = (dfs(r + 1, c, i + 1) or dfs(r - 1, c, i + 1) or
                 dfs(r, c + 1, i + 1) or dfs(r, c - 1, i + 1))
        board[r][c] = word[i]                 # restore when going back
        return found

    return any(dfs(r, c, 0) for r in range(rows) for c in range(cols))

