    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]   # nothing to change
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],      # delete
                                   dp[i][j - 1],      # insert
                                   dp[i - 1][j - 1])  # replace
    return dp[m][n]

def knapsack(weights, values, capacity):
    best = [0] * (capacity + 1)               # best[c]: max value within capacity c
    for w, v in zip(weights, values):
        for c in range(capacity, w - 1, -1):  # downwards: each item at most once
            best[c] = max(best[c], best[c - w] + v)
    return best[capacity]

def find_target_sum_ways(nums, target):
    total = sum(nums)
    if abs(target) > total or (total + target) % 2:
        return 0
    goal = (total + target) // 2              # sum of the "+" numbers
    ways = [1] + [0] * goal                   # ways[s]: subsets that sum to s
    for x in nums:
        for s in range(goal, x - 1, -1):      # downwards: each number once
            ways[s] += ways[s - x]
    return ways[goal]

def maximal_square(matrix):
    rows, cols = len(matrix), len(matrix[0])
    dp = [[0] * (cols + 1) for _ in range(rows + 1)]   # padded with zeros
    best = 0
    for r in range(1, rows + 1):
        for c in range(1, cols + 1):
            if matrix[r - 1][c - 1] == "1":
                dp[r][c] = 1 + min(dp[r - 1][c], dp[r][c - 1], dp[r - 1][c - 1])
                best = max(best, dp[r][c])
    return best * best

def is_interleave(s1, s2, s3):
    m, n = len(s1), len(s2)
    if m + n != len(s3):
        return False
    dp = [[False] * (n + 1) for _ in range(m + 1)]   # s1[:i] + s2[:j] -> s3[:i + j]?
    dp[0][0] = True
    for i in range(m + 1):
        for j in range(n + 1):
            if i > 0 and dp[i - 1][j] and s1[i - 1] == s3[i + j - 1]:
                dp[i][j] = True                     # last char came from s1
            if j > 0 and dp[i][j - 1] and s2[j - 1] == s3[i + j - 1]:
                dp[i][j] = True                     # last char came from s2
    return dp[m][n]

def minimum_total(triangle):
    best = triangle[-1][:]                    # start with the bottom row
    for r in range(len(triangle) - 2, -1, -1):
        for c in range(r + 1):
            best[c] = triangle[r][c] + min(best[c], best[c + 1])
    return best[0]

from functools import cache

def longest_increasing_path(matrix):
    rows, cols = len(matrix), len(matrix[0])

    @cache
    def longest_from(r, c):                   # longest path starting at (r, c)
        best = 1
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols and matrix[nr][nc] > matrix[r][c]:
                best = max(best, 1 + longest_from(nr, nc))
        return best

    return max(longest_from(r, c) for r in range(rows) for c in range(cols))

def num_distinct(s, t):
    ways = [1] + [0] * len(t)                 # ways[j]: ways to form t[:j]
    for ch in s:
        for j in range(len(t), 0, -1):        # downwards: use ch once per j
            if t[j - 1] == ch:
                ways[j] += ways[j - 1]
    return ways[len(t)]

from functools import cache

def is_match(s, p):
    @cache
    def match(i, j):                          # does s[i:] match p[j:]?
        if j == len(p):
            return i == len(s)
        first = i < len(s) and p[j] in (s[i], ".")
        if j + 1 < len(p) and p[j + 1] == "*":
            # Skip "x*" completely, or let it eat one character and stay.
            return match(i, j + 2) or (first and match(i + 1, j))
        return first and match(i + 1, j + 1)

    return match(0, 0)

class TrieNode:
    def __init__(self):
        self.children = {}               # letter -> TrieNode
        self.is_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, TrieNode())
        node.is_word = True

    def _walk(self, text):               # the node at the end of text, or None
        node = self.root
        for ch in text:
            node = node.children.get(ch)
            if node is None:
                return None
        return node

    def search(self, word):
        node = self._walk(word)
        return node is not None and node.is_word

    def starts_with(self, prefix):
        return self._walk(prefix) is not None

class WordDictionary:
    def __init__(self):
        self.root = {}                   # nested dicts, "$" marks a word end

    def add_word(self, word):
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node["$"] = True

    def search(self, word):
        def dfs(node, i):
            if i == len(word):
                return "$" in node
            ch = word[i]
            if ch == ".":                # any letter: try every child
                return any(dfs(child, i + 1) for key, child in node.items() if key != "$")
            return ch in node and dfs(node[ch], i + 1)

        return dfs(self.root, 0)

def find_words(board, words):
    root = {}
    for w in words:                           # trie of every word
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
        node["$"] = w                         # the word ends here
    rows, cols = len(board), len(board[0])
    found = []

    def dfs(r, c, parent):
        ch = board[r][c]
        node = parent[ch]
        if "$" in node:
            found.append(node.pop("$"))       # record it once
        board[r][c] = "#"                     # used on this path
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols and board[nr][nc] in node:
                dfs(nr, nc, node)
        board[r][c] = ch                      # restore
        if not node:
            parent.pop(ch)                    # prune a finished branch

    for r in range(rows):
        for c in range(cols):
            if board[r][c] in root:
                dfs(r, c, root)
    return found

import bisect

def suggested_products(products, search_word):
    products = sorted(products)
    result, prefix = [], ""
    for ch in search_word:
        prefix += ch
        i = bisect.bisect_left(products, prefix)          # first product >= prefix
        result.append([p for p in products[i:i + 3] if p.startswith(prefix)])
    return result

def suggested_products_trie(products, search_word):
    root = {}
    for p in sorted(products):
        node = root
        for ch in p:
            node = node.setdefault(ch, {})
            node.setdefault("#", [])                      # "#": up to 3 suggestions
            if len(node["#"]) < 3:
                node["#"].append(p)
    result, node = [], root
    for ch in search_word:
        node = node.get(ch, {})                           # {} once nothing matches
        result.append(node.get("#", []))
    return result

