        count += 1
    return count

def count_bits(n):
    bits = [0] * (n + 1)
    for i in range(1, n + 1):
        bits[i] = bits[i >> 1] + (i & 1)    # i without its last bit, plus that bit
    return bits

def reverse_bits(n):
    result = 0
    for _ in range(32):
        result = (result << 1) | (n & 1)     # move n's last bit onto result
        n >>= 1
    return result

def missing_number(nums):
