    for x in nums:
        both ^= x                        # = a ^ b
    bit = both & -both                   # a bit where a and b differ
    a = b = 0
    for x in nums:
        if x & bit:                      # split by that bit
            a ^= x
        else:
            b ^= x
    return sorted([a, b])

def set_zeroes(matrix):
