def count_inversions(nums):
    def sort_count(a):                        # returns (sorted a, inversions in a)
        if len(a) <= 1:
            return a, 0
        mid = len(a) // 2
        left, inv_left = sort_count(a[:mid])
        right, inv_right = sort_count(a[mid:])
        merged, i, j = [], 0, 0
        inv = inv_left + inv_right
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                inv += len(left) - i          # smaller than every waiting left item
                j += 1
        merged += left[i:] + right[j:]
        return merged, inv

    return sort_count(nums)[1]

class Node:
    def __init__(self, key=0, val=0):
        self.key, self.val = key, val
        self.prev = self.next = None

class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.map = {}                              # key -> node
        self.head, self.tail = Node(), Node()      # dummies: head.next is the newest
        self.head.next, self.tail.prev = self.tail, self.head

    def _remove(self, node):
        node.prev.next, node.next.prev = node.next, node.prev

    def _add_front(self, node):
        node.prev, node.next = self.head, self.head.next
        self.head.next.prev = node
        self.head.next = node

    def get(self, key):
        if key not in self.map:
            return -1
        node = self.map[key]
        self._remove(node)                         # now the most recently used
        self._add_front(node)
        return node.val

    def put(self, key, value):
        if key in self.map:
            self._remove(self.map[key])
        node = Node(key, value)
        self.map[key] = node
        self._add_front(node)
        if len(self.map) > self.capacity:
            lru = self.tail.prev                   # least recently used
            self._remove(lru)
            del self.map[lru.key]

from collections import defaultdict, OrderedDict

class LFUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.info = {}                              # key -> [value, count]
        self.groups = defaultdict(OrderedDict)      # count -> keys, oldest first
        self.min_count = 0

    def _touch(self, key):                          # one more use of key
        count = self.info[key][1]
        del self.groups[count][key]
        if not self.groups[count]:
            del self.groups[count]
            if self.min_count == count:
                self.min_count += 1
        self.groups[count + 1][key] = None
        self.info[key][1] = count + 1

    def get(self, key):
        if key not in self.info:
            return -1
        self._touch(key)
        return self.info[key][0]

    def put(self, key, value):
        if self.capacity <= 0:
            return
        if key in self.info:
            self.info[key][0] = value
            self._touch(key)
            return
        if len(self.info) >= self.capacity:
            old, _ = self.groups[self.min_count].popitem(last=False)   # LFU, then LRU
            if not self.groups[self.min_count]:
                del self.groups[self.min_count]
            del self.info[old]
        self.info[key] = [value, 1]
        self.groups[1][key] = None
        self.min_count = 1

class MyQueue:
    def __init__(self):
        self.inbox, self.outbox = [], []

    def push(self, x):
        self.inbox.append(x)

    def _refill(self):
        if not self.outbox:                     # only when empty: keeps FIFO order
            while self.inbox:
                self.outbox.append(self.inbox.pop())

    def pop(self):
        self._refill()
        return self.outbox.pop()

    def peek(self):
        self._refill()
        return self.outbox[-1]

    def empty(self):
        return not self.inbox and not self.outbox

