class RandomizedSet:
    def __init__(self):
        self.values = []                 # for O(1) random picks
        self.index = {}                  # value -> its position in values

    def insert(self, val):
        if val in self.index:
            return False
        self.index[val] = len(self.values)
        self.values.append(val)
        return True

    def remove(self, val):
        if val not in self.index:
            return False
        i, last = self.index[val], self.values[-1]
        self.values[i] = last            # move the last value into the hole
        self.index[last] = i
        self.values.pop()
        del self.index[val]
        return True

    def get_random(self):
        return random.choice(self.values)

class MyHashMap:
    def __init__(self, size=1024):
        self.buckets = [[] for _ in range(size)]   # separate chaining

    def _bucket(self, key):
        return self.buckets[hash(key) % len(self.buckets)]

    def put(self, key, value):
        bucket = self._bucket(key)
        for pair in bucket:
            if pair[0] == key:
                pair[1] = value                    # update in place
                return
        bucket.append([key, value])

    def get(self, key):
        for k, v in self._bucket(key):
            if k == key:
                return v
        return -1

