        ch, start = chars[read], read
        while read < len(chars) and chars[read] == ch:
            read += 1                          # skip the whole group
        chars[write] = ch
        write += 1
        if read - start > 1:
            for digit in str(read - start):    # 12 becomes "1", "2"
                chars[write] = digit
                write += 1
    return write

def reverse_words(s):
    words, i, n = [], 0, len(s)
    while i < n:
        while i < n and s[i] == " ":
            i += 1                             # skip spaces
        start = i
        while i < n and s[i] != " ":
            i += 1                             # read one word
        if start < i:
            words.append(s[start:i])
    left, right = 0, len(words) - 1
    while left < right:                        # reverse the word order
        words[left], words[right] = words[right], words[left]
        left += 1
        right -= 1
    return " ".join(words)

def int_to_roman(num):
    table = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"),
             (90, "XC"), (50, "L"), (40, "XL"), (10, "X"), (9, "IX"),
             (5, "V"), (4, "IV"), (1, "I")]
    parts = []
    for value, symbol in table:
        count, num = divmod(num, value)        # how many times it fits
        parts.append(symbol * count)
    return "".join(parts)

